import numpy as np, itertools
lines=open('opt.xyz').read().split('\n'); n=int(lines[0])
els=[];xyz=[]
for l in lines[2:2+n]:
    p=l.split(); els.append(p[0]); xyz.append(list(map(float,p[1:4])))
xyz=np.array(xyz)
cov={'H':0.31,'C':0.76,'N':0.71,'Ru':1.46}
bonds={}
for i,j in itertools.combinations(range(n),2):
    d=np.linalg.norm(xyz[i]-xyz[j])
    if d < cov[els[i]]+cov[els[j]]+0.45:
        bonds.setdefault(i,[]).append(j); bonds.setdefault(j,[]).append(i)
from collections import Counter
print(Counter(len(v) for v in bonds.values()))
# Ru neighbors
print("Ru nbrs:", [(i,els[i],round(np.linalg.norm(xyz[0]-xyz[i]),2)) for i in bonds[0]])
# check each C,H count
for i,e in enumerate(els):
    if e=='C':
        nh=sum(1 for j in bonds[i] if els[j]=='H')
        nc=sum(1 for j in bonds[i] if els[j]=='C')
        nn=sum(1 for j in bonds[i] if els[j]=='N')
        nr=sum(1 for j in bonds[i] if els[j]=='Ru')
        if nh>0 and nh!=3 and not (i in (62,63,64)):
            print("odd CH", i, nh, nc, nn)
# alkyne
print("C62 nbrs", bonds[62], "C63 nbrs", bonds[63], "H64 nbrs", bonds[64])
# mesityl ipso check: C bonded to N should have 3 C nbrs, 0 H
for iN in (10,36):
    for j in bonds[iN]:
        if els[j]=='C':
            print("N",iN,"-> C",j,"nbrs",[(k,els[k]) for k in bonds[j]])
# formula
print(Counter(els))
